# -----------------------------
# SEARCH NORMALIZATION FUNCTION
# -----------------------------
def normalize_search(text):
    text = text.lower().strip()
    terms = {text}

    if text.endswith("ies"):
        terms.add(text[:-3] + "y")
    if text.endswith("ves"):
        terms.add(text[:-3] + "f")
        terms.add(text[:-3] + "fe")
    if text.endswith("s"):
        terms.add(text[:-1])

    return list(terms)

